import React, { useState, useEffect } from 'react';
import { 
  Card, 
  Button, 
  Space, 
  Typography, 
  message, 
  Row, 
  Col,
  Progress,
  Modal
} from 'antd';
import { DownloadOutlined, ReloadOutlined } from '@ant-design/icons';

const { Title, Text } = Typography;

const TestPinyin = () => {
  const [questions, setQuestions] = useState([]);
  const [answers, setAnswers] = useState({});
  const [isTestStarted, setIsTestStarted] = useState(false);
  const [isTestCompleted, setIsTestCompleted] = useState(false);
  const [score, setScore] = useState(0);
  const [showResults, setShowResults] = useState(false);

  // 拼音数据库
  const pinyinDatabase = [
    'b', 'p', 'm', 'f', 'd', 't', 'n', 'l', 'g', 'k', 'h', 'j', 'q', 'x', 'zh', 'ch', 'sh', 'r', 'z', 'c', 's', 'y', 'w',
    'a', 'o', 'e', 'i', 'u', 'ü', 'ai', 'ei', 'ui', 'ao', 'ou', 'iu', 'ie', 'üe', 'er', 'an', 'en', 'in', 'un', 'ün', 'ang', 'eng', 'ing', 'ong',
    'zhi', 'chi', 'shi', 'ri', 'zi', 'ci', 'si', 'yi', 'wu', 'yu', 'ye', 'yue', 'yin', 'yun', 'yuan', 'ying',
    'ma', 'ba', 'pa', 'fa', 'da', 'ta', 'na', 'la', 'ga', 'ka', 'ha', 'za', 'ca', 'sa', 'ya', 'wa',
    'mo', 'bo', 'po', 'fo', 'lo', 'wo', 'yo',
    'me', 'de', 'te', 'ne', 'le', 'ge', 'ke', 'he', 'ze', 'ce', 'se', 're',
    'mi', 'bi', 'pi', 'di', 'ti', 'ni', 'li', 'ji', 'qi', 'xi', 'yi',
    'mu', 'bu', 'pu', 'fu', 'du', 'tu', 'nu', 'lu', 'gu', 'ku', 'hu', 'zu', 'cu', 'su', 'ru', 'wu',
    'nü', 'lü', 'ju', 'qu', 'xu', 'yu',
    'mai', 'bai', 'pai', 'dai', 'tai', 'nai', 'lai', 'gai', 'kai', 'hai', 'zai', 'cai', 'sai',
    'mei', 'bei', 'pei', 'fei', 'dei', 'tei', 'nei', 'lei', 'gei', 'kei', 'hei', 'zei', 'cei', 'sei',
    'mao', 'bao', 'pao', 'dao', 'tao', 'nao', 'lao', 'gao', 'kao', 'hao', 'zao', 'cao', 'sao', 'rao',
    'mou', 'pou', 'fou', 'dou', 'tou', 'nou', 'lou', 'gou', 'kou', 'hou', 'zou', 'cou', 'sou', 'rou',
    'man', 'ban', 'pan', 'fan', 'dan', 'tan', 'nan', 'lan', 'gan', 'kan', 'han', 'zan', 'can', 'san', 'ran',
    'men', 'ben', 'pen', 'fen', 'den', 'nen', 'gen', 'ken', 'hen', 'zen', 'cen', 'sen', 'ren',
    'min', 'bin', 'pin', 'nin', 'lin', 'jin', 'qin', 'xin', 'yin',
    'mang', 'bang', 'pang', 'fang', 'dang', 'tang', 'nang', 'lang', 'gang', 'kang', 'hang', 'zang', 'cang', 'sang', 'rang',
    'meng', 'beng', 'peng', 'feng', 'deng', 'teng', 'neng', 'leng', 'geng', 'keng', 'heng', 'zeng', 'ceng', 'seng', 'reng',
    'ming', 'bing', 'ping', 'ding', 'ting', 'ning', 'ling', 'jing', 'qing', 'xing', 'ying',
    'miao', 'biao', 'piao', 'diao', 'tiao', 'niao', 'liao', 'jiao', 'qiao', 'xiao', 'yao',
    'mie', 'bie', 'pie', 'die', 'tie', 'nie', 'lie', 'jie', 'qie', 'xie', 'ye',
    'miu', 'diu', 'niu', 'liu', 'jiu', 'qiu', 'xiu',
    'mian', 'bian', 'pian', 'dian', 'tian', 'nian', 'lian', 'jian', 'qian', 'xian', 'yan',
    'mā', 'má', 'mǎ', 'mà', 'bā', 'bá', 'bǎ', 'bà', 'pā', 'pá', 'pǎ', 'pà',
    'dā', 'dá', 'dǎ', 'dà', 'tā', 'tá', 'tǎ', 'tà', 'nā', 'ná', 'nǎ', 'nà',
    'lā', 'lá', 'lǎ', 'là', 'gā', 'gá', 'gǎ', 'gà', 'kā', 'ká', 'kǎ', 'kà',
    'hā', 'há', 'hǎ', 'hà', 'zhā', 'zhá', 'zhǎ', 'zhà', 'chā', 'chá', 'chǎ', 'chà',
    'shā', 'shá', 'shǎ', 'shà', 'rā', 'rá', 'rǎ', 'rà', 'zā', 'zá', 'zǎ', 'zà',
    'cā', 'cá', 'cǎ', 'cà', 'sā', 'sá', 'sǎ', 'sà', 'yā', 'yá', 'yǎ', 'yà',
    'wā', 'wá', 'wǎ', 'wà', 'jiā', 'jiá', 'jiǎ', 'jià', 'qiā', 'qiá', 'qiǎ', 'qià',
    'xiā', 'xiá', 'xiǎ', 'xià', 'niā', 'niá', 'niǎ', 'nià', 'liā', 'liá', 'liǎ', 'lià'
  ];

  // 生成30道拼音题目
  const generateTest = () => {
    const newQuestions = [];
    const usedPinyin = new Set();

    for (let i = 0; i < 30; i++) {
      let pinyin;
      do {
        pinyin = pinyinDatabase[Math.floor(Math.random() * pinyinDatabase.length)];
      } while (usedPinyin.has(pinyin));
      
      usedPinyin.add(pinyin);
      
      newQuestions.push({
        id: i,
        pinyin: pinyin,
        row: Math.floor(i / 10) + 1,
        column: (i % 10) + 1
      });
    }
    
    setQuestions(newQuestions);
    setAnswers({});
    setIsTestStarted(true);
    setIsTestCompleted(false);
    setScore(0);
    setShowResults(false);
  };

  // 计算分数
  const calculateScore = () => {
    const totalQuestions = questions.length;
    const correctAnswers = Object.values(answers).filter(answer => answer === true).length;
    const score = Math.round((correctAnswers / totalQuestions) * 100);
    return score;
  };

  // 完成测试
  const completeTest = () => {
    const unanswered = questions.filter(question => answers[question.pinyin] === null || answers[question.pinyin] === undefined);
    
    if (unanswered.length > 0) {
      message.warning(`还有 ${unanswered.length} 个拼音没有选择答案，请完成所有题目后再提交。`);
      return;
    }

    const finalScore = calculateScore();
    setScore(finalScore);
    setIsTestCompleted(true);
    setShowResults(true);
  };

  // 下载测试结果
  const downloadResults = () => {
    const today = new Date().toISOString().split('T')[0];
    const filename = `pinyin-${today}.json`;
    
    const results = questions.map(question => ({
      d1: question.pinyin,
      t1: answers[question.pinyin] || false
    }));

    const dataStr = JSON.stringify(results, null, 2);
    const dataBlob = new Blob([dataStr], { type: 'application/json' });
    
    const link = document.createElement('a');
    link.href = URL.createObjectURL(dataBlob);
    link.download = filename;
    link.click();
    
    message.success(`测试结果已下载为 ${filename}`);
  };

  // 重新开始测试
  const restartTest = () => {
    setIsTestStarted(false);
    setIsTestCompleted(false);
    setQuestions([]);
    setAnswers({});
    setScore(0);
    setShowResults(false);
  };

  return (
    <div style={{ padding: '24px', maxWidth: '1200px', margin: '0 auto' }}>
      <Title level={2}>拼音拼读测验</Title>

      {!isTestStarted ? (
        <Card style={{ marginBottom: '24px' }}>
          <Row gutter={16} align="middle">
            <Col>
              <Text strong>拼音拼读测验说明：</Text>
              <br />
              <Text type="secondary">
                点击拼音卡片进行选择，绿色表示读对，红色表示读错
              </Text>
            </Col>
            <Col>
              <Button type="primary" size="large" onClick={generateTest}>
                开始测验
              </Button>
            </Col>
          </Row>
        </Card>
      ) : (
        <>
          <Card style={{ marginBottom: '24px' }}>
            <Row justify="space-between" align="middle">
              <Col>
                <Text strong>拼音拼读测验</Text>
                <br />
                <Text type="secondary">
                  题目数量：{questions.length} 个拼音
                </Text>
              </Col>
              <Col>
                <Text strong>完成进度：</Text>
                <Progress
                  percent={Math.round((Object.keys(answers).length / questions.length) * 100)}
                  size="small"
                  style={{ width: 200 }}
                />
              </Col>
              <Col>
                <Space>
                  {!isTestCompleted && (
                    <Button type="primary" onClick={completeTest}>
                      完成测验
                    </Button>
                  )}
                  <Button onClick={restartTest}>
                    重新开始
                  </Button>
                </Space>
              </Col>
            </Row>
          </Card>

          <Card>
            <div style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
              {Array.from({ length: Math.ceil(questions.length / 10) }, (_, rowIndex) => (
                <div key={rowIndex} style={{ display: 'flex', gap: '16px', justifyContent: 'flex-start' }}>
                  {questions.slice(rowIndex * 10, (rowIndex + 1) * 10).map((question) => (
                    <Card
                      key={question.pinyin}
                      style={{
                        width: '100px',
                        textAlign: 'center',
                        cursor: 'pointer',
                        backgroundColor: answers[question.pinyin] === true ? '#f6ffed' : 
                                      answers[question.pinyin] === false ? '#fff1f0' : '#fff',
                        border: answers[question.pinyin] === true ? '2px solid #52c41a' : 
                               answers[question.pinyin] === false ? '2px solid #ff4d4f' : '1px solid #d9d9d9'
                      }}
                      bodyStyle={{ padding: '12px' }}
                      onClick={() => {
                        if (isTestCompleted) return;
                        
                        const newAnswers = {...answers};
                        if (answers[question.pinyin] === undefined) {
                          newAnswers[question.pinyin] = true;
                        } else if (answers[question.pinyin] === true) {
                          newAnswers[question.pinyin] = false;
                        } else {
                          delete newAnswers[question.pinyin];
                        }
                        setAnswers(newAnswers);
                      }}
                    >
                      <div style={{ 
                        fontSize: '20px', 
                        marginBottom: '8px',
                        fontWeight: 'bold',
                        color: answers[question.pinyin] === true ? '#52c41a' : 
                               answers[question.pinyin] === false ? '#ff4d4f' : '#1890ff'
                      }}>
                        {question.pinyin}
                      </div>
                      <div style={{ fontSize: '12px', color: '#666' }}>
                        {answers[question.pinyin] === true ? '读对' : 
                         answers[question.pinyin] === false ? '读错' : '点击选择'}
                      </div>
                    </Card>
                  ))}
                </div>
              ))}
            </div>
          </Card>

          <Modal
            title="测验结果"
            open={showResults}
            onCancel={() => setShowResults(false)}
            footer={[
              <Button key="download" type="primary" icon={<DownloadOutlined />} onClick={downloadResults}>
                下载结果
              </Button>,
              <Button key="restart" icon={<ReloadOutlined />} onClick={restartTest}>
                重新测验
              </Button>,
              <Button key="close" onClick={() => setShowResults(false)}>
                关闭
              </Button>
            ]}
            width={600}
          >
            <div style={{ textAlign: 'center', padding: '20px 0' }}>
              <Title level={1} style={{ color: score >= 80 ? '#52c41a' : score >= 60 ? '#faad14' : '#ff4d4f' }}>
                {score} 分
              </Title>
              <Text style={{ fontSize: '16px' }}>
                {score >= 80 ? '优秀！' : score >= 60 ? '良好！' : '需要继续努力！'}
              </Text>
              <br />
              <Text type="secondary">
                正确掌握：{Object.values(answers).filter(a => a === true).length} 个拼音
              </Text>
              <br />
              <Text type="secondary">
                需要加强：{Object.values(answers).filter(a => a === false).length} 个拼音
              </Text>
            </div>
          </Modal>
        </>
      )}
    </div>
  );
};

export default TestPinyin; 