import React, { useState } from 'react';
import { Layout, Menu } from 'antd';

const { Sider, Content } = Layout;

const EnglishPage = () => {
  const [selectedKey, setSelectedKey] = useState('alphabet');

  const menuItems = [
    {
      key: 'alphabet',
      label: '英文字母',
    },
    {
      key: 'nouns',
      label: '名词',
    },
    {
      key: 'verbs',
      label: '动词',
    },
    {
      key: 'adjectives',
      label: '形容词',
    },
    {
      key: 'be-verbs',
      label: 'Be动词',
    },
    {
      key: 'tenses',
      label: '时态结构',
    },
    {
      key: 'plural',
      label: '名词单复数',
    },
    {
      key: 'questions',
      label: '疑问词运用',
    },
  ];

  const renderContent = () => {
    switch (selectedKey) {
      case 'alphabet':
        return (
          <div>
            <h2>英文字母学习</h2>
            <p>学习26个英文字母的发音和书写</p>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(7, 1fr)', gap: '10px', marginTop: '20px' }}>
              {Array.from('ABCDEFGHIJKLMNOPQRSTUVWXYZ').map((letter, index) => (
                <div
                  key={index}
                  style={{
                    border: '2px solid #1890ff',
                    borderRadius: '8px',
                    padding: '20px',
                    textAlign: 'center',
                    fontSize: '24px',
                    fontWeight: 'bold',
                    backgroundColor: '#f0f8ff',
                    cursor: 'pointer',
                    transition: 'all 0.3s'
                  }}
                  onMouseEnter={(e) => {
                    e.target.style.transform = 'scale(1.1)';
                    e.target.style.backgroundColor = '#e6f7ff';
                  }}
                  onMouseLeave={(e) => {
                    e.target.style.transform = 'scale(1)';
                    e.target.style.backgroundColor = '#f0f8ff';
                  }}
                >
                  {letter}
                </div>
              ))}
            </div>
          </div>
        );
      case 'nouns':
        return (
          <div>
            <h2>名词学习</h2>
            <p>学习常用英语名词</p>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '15px', marginTop: '20px' }}>
              {['apple', 'book', 'cat', 'dog', 'elephant', 'flower', 'girl', 'house', 'ice cream'].map((noun, index) => (
                <div
                  key={index}
                  style={{
                    border: '1px solid #d9d9d9',
                    borderRadius: '8px',
                    padding: '15px',
                    textAlign: 'center',
                    backgroundColor: '#fafafa'
                  }}
                >
                  <div style={{ fontSize: '18px', fontWeight: 'bold', marginBottom: '5px' }}>{noun}</div>
                  <div style={{ fontSize: '14px', color: '#666' }}>名词</div>
                </div>
              ))}
            </div>
          </div>
        );
      case 'verbs':
        return (
          <div>
            <h2>动词学习</h2>
            <p>学习常用英语动词</p>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '15px', marginTop: '20px' }}>
              {['run', 'jump', 'eat', 'sleep', 'play', 'read', 'write', 'sing', 'dance'].map((verb, index) => (
                <div
                  key={index}
                  style={{
                    border: '1px solid #d9d9d9',
                    borderRadius: '8px',
                    padding: '15px',
                    textAlign: 'center',
                    backgroundColor: '#fafafa'
                  }}
                >
                  <div style={{ fontSize: '18px', fontWeight: 'bold', marginBottom: '5px' }}>{verb}</div>
                  <div style={{ fontSize: '14px', color: '#666' }}>动词</div>
                </div>
              ))}
            </div>
          </div>
        );
      case 'adjectives':
        return (
          <div>
            <h2>形容词学习</h2>
            <p>学习常用英语形容词</p>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '15px', marginTop: '20px' }}>
              {['big', 'small', 'happy', 'sad', 'hot', 'cold', 'fast', 'slow', 'beautiful'].map((adj, index) => (
                <div
                  key={index}
                  style={{
                    border: '1px solid #d9d9d9',
                    borderRadius: '8px',
                    padding: '15px',
                    textAlign: 'center',
                    backgroundColor: '#fafafa'
                  }}
                >
                  <div style={{ fontSize: '18px', fontWeight: 'bold', marginBottom: '5px' }}>{adj}</div>
                  <div style={{ fontSize: '14px', color: '#666' }}>形容词</div>
                </div>
              ))}
            </div>
          </div>
        );
      case 'be-verbs':
        return (
          <div>
            <h2>Be动词学习</h2>
            <p>学习Be动词的用法</p>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '15px', marginTop: '20px' }}>
              {[
                { verb: 'am', usage: 'I am' },
                { verb: 'is', usage: 'He/She/It is' },
                { verb: 'are', usage: 'We/You/They are' }
              ].map((item, index) => (
                <div
                  key={index}
                  style={{
                    border: '2px solid #52c41a',
                    borderRadius: '8px',
                    padding: '20px',
                    textAlign: 'center',
                    backgroundColor: '#f6ffed'
                  }}
                >
                  <div style={{ fontSize: '24px', fontWeight: 'bold', marginBottom: '10px' }}>{item.verb}</div>
                  <div style={{ fontSize: '16px', color: '#666' }}>{item.usage}</div>
                </div>
              ))}
            </div>
          </div>
        );
      case 'tenses':
        return (
          <div>
            <h2>时态结构学习</h2>
            <p>学习基本英语时态</p>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(2, 1fr)', gap: '20px', marginTop: '20px' }}>
              {[
                { tense: '一般现在时', example: 'I play football.' },
                { tense: '一般过去时', example: 'I played football.' },
                { tense: '现在进行时', example: 'I am playing football.' },
                { tense: '一般将来时', example: 'I will play football.' }
              ].map((item, index) => (
                <div
                  key={index}
                  style={{
                    border: '1px solid #d9d9d9',
                    borderRadius: '8px',
                    padding: '20px',
                    backgroundColor: '#fafafa'
                  }}
                >
                  <div style={{ fontSize: '18px', fontWeight: 'bold', marginBottom: '10px' }}>{item.tense}</div>
                  <div style={{ fontSize: '16px', color: '#666' }}>{item.example}</div>
                </div>
              ))}
            </div>
          </div>
        );
      case 'plural':
        return (
          <div>
            <h2>名词单复数学习</h2>
            <p>学习名词的单复数形式</p>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(2, 1fr)', gap: '20px', marginTop: '20px' }}>
              {[
                { singular: 'book', plural: 'books' },
                { singular: 'cat', plural: 'cats' },
                { singular: 'child', plural: 'children' },
                { singular: 'foot', plural: 'feet' }
              ].map((item, index) => (
                <div
                  key={index}
                  style={{
                    border: '1px solid #d9d9d9',
                    borderRadius: '8px',
                    padding: '20px',
                    textAlign: 'center',
                    backgroundColor: '#fafafa'
                  }}
                >
                  <div style={{ fontSize: '16px', marginBottom: '5px' }}>
                    <span style={{ color: '#666' }}>单数: </span>
                    <span style={{ fontWeight: 'bold' }}>{item.singular}</span>
                  </div>
                  <div style={{ fontSize: '16px' }}>
                    <span style={{ color: '#666' }}>复数: </span>
                    <span style={{ fontWeight: 'bold' }}>{item.plural}</span>
                  </div>
                </div>
              ))}
            </div>
          </div>
        );
      case 'questions':
        return (
          <div>
            <h2>疑问词运用</h2>
            <p>学习常用疑问词</p>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '15px', marginTop: '20px' }}>
              {[
                { word: 'What', usage: '什么' },
                { word: 'Where', usage: '哪里' },
                { word: 'When', usage: '什么时候' },
                { word: 'Who', usage: '谁' },
                { word: 'Why', usage: '为什么' },
                { word: 'How', usage: '怎么样' }
              ].map((item, index) => (
                <div
                  key={index}
                  style={{
                    border: '2px solid #722ed1',
                    borderRadius: '8px',
                    padding: '20px',
                    textAlign: 'center',
                    backgroundColor: '#f9f0ff'
                  }}
                >
                  <div style={{ fontSize: '20px', fontWeight: 'bold', marginBottom: '10px' }}>{item.word}</div>
                  <div style={{ fontSize: '16px', color: '#666' }}>{item.usage}</div>
                </div>
              ))}
            </div>
          </div>
        );
      default:
        return <div>功能开发中...</div>;
    }
  };

  return (
    <Layout style={{ minHeight: '100vh' }}>
      <Sider width={200} theme="light">
        <Menu
          mode="inline"
          selectedKeys={[selectedKey]}
          style={{ height: '100%', borderRight: 0 }}
          items={menuItems}
          onClick={({ key }) => setSelectedKey(key)}
        />
      </Sider>
      <Layout>
        <Content style={{ padding: '24px', minHeight: 280 }}>
          {renderContent()}
        </Content>
      </Layout>
    </Layout>
  );
};

export default EnglishPage; 