import React, { useState, useEffect } from 'react';
import { Button, Input, Card, Progress, message, Space, Typography, Divider } from 'antd';
import { DownloadOutlined, ReloadOutlined, CheckCircleOutlined, CloseCircleOutlined } from '@ant-design/icons';

const { Title, Text } = Typography;

const TestAddition = () => {
  const [questions, setQuestions] = useState([]);
  const [answers, setAnswers] = useState({});
  const [isSubmitted, setIsSubmitted] = useState(false);
  const [score, setScore] = useState(0);
  const [wrongAnswers, setWrongAnswers] = useState([]);
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);

  // 生成20以内的随机加减法题目
  const generateQuestions = () => {
    const newQuestions = [];
    for (let i = 0; i < 10; i++) {
      const isAddition = Math.random() > 0.5; // 50%概率生成加法或减法
      
      if (isAddition) {
        // 生成加法题目，确保结果不超过20
        const num1 = Math.floor(Math.random() * 20) + 1; // 1-20
        const maxNum2 = 20 - num1; // 确保 num1 + num2 <= 20
        const num2 = Math.floor(Math.random() * maxNum2) + 1; // 1到maxNum2
        const correctAnswer = num1 + num2;
        
        newQuestions.push({
          id: i,
          question: `${num1} + ${num2} = ?`,
          num1,
          num2,
          operator: '+',
          correctAnswer
        });
      } else {
        // 生成减法题目，确保结果不小于0
        const num1 = Math.floor(Math.random() * 20) + 1; // 1-20
        const num2 = Math.floor(Math.random() * num1) + 1; // 1到num1，确保num1 >= num2
        const correctAnswer = num1 - num2;
        
        newQuestions.push({
          id: i,
          question: `${num1} - ${num2} = ?`,
          num1,
          num2,
          operator: '-',
          correctAnswer
        });
      }
    }
    setQuestions(newQuestions);
    setAnswers({});
    setIsSubmitted(false);
    setScore(0);
    setWrongAnswers([]);
    setCurrentQuestionIndex(0);
  };

  // 初始化题目
  useEffect(() => {
    generateQuestions();
  }, []);

  // 处理答案输入
  const handleAnswerChange = (questionId, value) => {
    setAnswers(prev => ({
      ...prev,
      [questionId]: parseInt(value) || ''
    }));
  };

  // 提交答案并评分
  const handleSubmit = () => {
    const answeredCount = Object.keys(answers).length;
    if (answeredCount < 10) {
      message.warning('请完成所有题目后再提交！');
      return;
    }

    let correctCount = 0;
    const wrong = [];

    questions.forEach(question => {
      const userAnswer = answers[question.id];
      const isCorrect = userAnswer === question.correctAnswer;
      
      if (isCorrect) {
        correctCount++;
      } else {
        wrong.push({
          d1: `${question.num1}${question.operator}${question.num2}=`,
          d2: userAnswer.toString(),
          t1: false
        });
      }
    });

    const finalScore = Math.round((correctCount / 10) * 100);
    setScore(finalScore);
    setWrongAnswers(wrong);
    setIsSubmitted(true);

    if (finalScore === 100) {
      message.success('恭喜你获得满分！');
    } else {
      message.info(`你的得分是：${finalScore}分`);
    }
  };

  // 下载错题结果
  const downloadWrongAnswers = () => {
    const data = score === 100 ? [] : wrongAnswers;
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    
    const today = new Date();
    const dateStr = today.toISOString().split('T')[0]; // YYYY-MM-DD格式
    link.download = `addition-${dateStr}.json`;
    
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
    
    message.success('错题结果已下载！');
  };

  // 重新开始测试
  const handleRestart = () => {
    generateQuestions();
  };

  return (
    <div style={{ padding: '20px', maxWidth: '800px', margin: '0 auto' }}>
      <Title level={2}>20以内加减法测试</Title>
      
      {!isSubmitted ? (
        <div>
          <div style={{ marginBottom: '20px' }}>
            <Space>
              <Text>题目进度：</Text>
              <Progress 
                percent={Math.round((Object.keys(answers).length / 10) * 100)} 
                status="active"
                style={{ width: '200px' }}
              />
              <Text>{Object.keys(answers).length}/10</Text>
            </Space>
          </div>

          <div style={{ 
            display: 'grid', 
            gridTemplateColumns: 'repeat(2, 1fr)', 
            gap: '15px', 
            marginBottom: '20px' 
          }}>
            {questions.map((question, index) => (
              <Card 
                key={question.id} 
                style={{ 
                  border: answers[question.id] !== undefined ? '2px solid #52c41a' : '1px solid #d9d9d9'
                }}
              >
                <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                  <div style={{ display: 'flex', alignItems: 'center' }}>
                    <Text strong style={{ marginRight: '10px', minWidth: '30px' }}>
                      {index + 1}.
                    </Text>
                    <Text style={{ fontSize: '18px', marginRight: '10px' }}>
                      {question.question}
                    </Text>
                  </div>
                  <Input
                    type="number"
                    placeholder="请输入答案"
                    value={answers[question.id] || ''}
                    onChange={(e) => handleAnswerChange(question.id, e.target.value)}
                    style={{ width: '120px' }}
                    onPressEnter={() => {
                      if (index < 9) {
                        const nextInput = document.querySelector(`input[data-index="${index + 1}"]`);
                        if (nextInput) nextInput.focus();
                      }
                    }}
                    data-index={index}
                  />
                </div>
              </Card>
            ))}
          </div>

          <div style={{ textAlign: 'center', marginTop: '20px' }}>
            <Space>
              <Button 
                type="primary" 
                size="large" 
                onClick={handleSubmit}
                disabled={Object.keys(answers).length < 10}
              >
                提交答案
              </Button>
              <Button 
                icon={<ReloadOutlined />} 
                size="large" 
                onClick={handleRestart}
              >
                重新开始
              </Button>
            </Space>
          </div>
        </div>
      ) : (
        <div>
          <Card style={{ textAlign: 'center', marginBottom: '20px' }}>
            <Title level={3}>
              {score === 100 ? (
                <span style={{ color: '#52c41a' }}>
                  <CheckCircleOutlined /> 恭喜获得满分！
                </span>
              ) : (
                <span style={{ color: score >= 80 ? '#faad14' : '#ff4d4f' }}>
                  <CloseCircleOutlined /> 测试完成
                </span>
              )}
            </Title>
            <div style={{ fontSize: '24px', fontWeight: 'bold', marginBottom: '10px' }}>
              得分：{score}分
            </div>
            <Progress 
              percent={score} 
              status={score === 100 ? 'success' : score >= 80 ? 'normal' : 'exception'}
              style={{ width: '300px', margin: '0 auto' }}
            />
            <div style={{ marginTop: '10px', color: '#666' }}>
              正确：{10 - wrongAnswers.length}题，错误：{wrongAnswers.length}题
            </div>
          </Card>

          {wrongAnswers.length > 0 && (
            <Card title="错题详情" style={{ marginBottom: '20px' }}>
              {wrongAnswers.map((wrong, index) => (
                <div key={index} style={{ 
                  padding: '10px', 
                  border: '1px solid #ffccc7', 
                  borderRadius: '4px', 
                  marginBottom: '5px',
                  backgroundColor: '#fff2f0'
                }}>
                  <Text>题目：{wrong.d1}</Text>
                  <br />
                  <Text type="danger">你的答案：{wrong.d2}</Text>
                </div>
              ))}
            </Card>
          )}

          <div style={{ textAlign: 'center' }}>
            <Space>
              <Button 
                type="primary" 
                icon={<DownloadOutlined />} 
                size="large" 
                onClick={downloadWrongAnswers}
              >
                下载错题结果
              </Button>
              <Button 
                icon={<ReloadOutlined />} 
                size="large" 
                onClick={handleRestart}
              >
                重新测试
              </Button>
            </Space>
          </div>
        </div>
      )}
    </div>
  );
};

export default TestAddition;
