                { question: '36 + 27 = ?', answer: '63', explanation: '6+7=13, 进1位' },
                { question: '45 + 38 = ?', answer: '83', explanation: '5+8=13, 进1位' },
                { question: '52 + 49 = ?', answer: '101', explanation: '2+9=11, 进1位' },
                { question: '67 + 34 = ?', answer: '101', explanation: '7+4=11, 进1位' },
                { question: '89 + 23 = ?', answer: '112', explanation: '9+3=12, 进1位' }
