        return (
          <div>
            <h2>进位减法</h2>
            <p>学习需要借位的减法运算</p>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '20px', marginTop: '20px' }}>
              {[
                { question: '42 - 15 = ?', answer: '27', explanation: '2不够减5, 借1位' },
                { question: '53 - 28 = ?', answer: '25', explanation: '3不够减8, 借1位' },
                { question: '61 - 34 = ?', answer: '27', explanation: '1不够减4, 借1位' },
                { question: '74 - 39 = ?', answer: '35', explanation: '4不够减9, 借1位' },
                { question: '86 - 47 = ?', answer: '39', explanation: '6不够减7, 借1位' },
                { question: '95 - 58 = ?', answer: '37', explanation: '5不够减8, 借1位' }
              ].map((item, index) => (
                <div
                  key={index}
                  style={{
                    border: '2px solid #eb2f96',
                    borderRadius: '8px',
                    padding: '20px',
                    textAlign: 'center',
                    backgroundColor: '#fff0f6'
                  }}
                >
                  <div style={{ fontSize: '20px', fontWeight: 'bold', marginBottom: '10px' }}>{item.question}</div>
                  <div style={{ fontSize: '18px', color: '#666', marginBottom: '5px' }}>答案: {item.answer}</div>
                  <div style={{ fontSize: '14px', color: '#999' }}>{item.explanation}</div>
                </div>
              ))}
            </div>
          </div>
        );
